@Component("dependent-handler")
@ProcessingGroup("dependent-processing-group")
public class DependentEventHandler {
	
	// core constructor
	DependentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDependentEvent
     */
    @EventHandler
    public void handle( CreateDependentEvent event) {
        entityManager.persist(new Dependent(event.getDependentId(), event.getFirstName(), event.getLastName(), event.getBirthDate(), event.getBenefitEnrollment(), event.getEmployee(), event.getRelationship()));
    }

    /*
     * @param	event UpdateDependentEvent
     */
    @EventHandler
    public Dependent handle( UpdateDependentEvent event) {
    	entityManager.merge(new Dependent(event.getDependentId(), event.getFirstName(), event.getLastName(), event.getBirthDate(), event.getBenefitEnrollment(), event.getEmployee(), event.getRelationship()));
    }
    
    /*
     * @param	event DeleteDependentEvent
     */
    @EventHandler
    public void on( DeleteDependentEvent event) {
    	Dependent entity = new Dependent();
   
    	// ------------------------------------------
    	// apply the DependentId
    	// ------------------------------------------
    	entity.setDependentId( event.getDependentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DependentRepository dependentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DependentEventHandler.class.getName());

}
